helpers.parse:
function parseResults(raw) {
 return String(raw).split(/\n?-{12,}\n/).map((chunk,rank)=>{
  const h=chunk.match(/^([^\n]+?) \((https?:\/\/[^\n]+)\)\s*\ncite([^]+)/);
  return h?{title:h[1].slice(0,500),url:h[2],ref:h[3],rank,body:chunk.slice(h[0].length).replace(/^.*(?:Crawled:|wordlim:|Published:).*$/gm,"").replace(/<visual_element[\s\S]*?<\/visual_element>/g,"")}:null;
 }).filter(Boolean);
}

helpers.excerpt:
function excerpt(text,query) {
 const stop=new Set("the and of with from which this are was were that have has its bolzano christianity bozen south tyrol in to a an is it by for on as at be or not into their according around wikipedia wikimedia org site".split(" "));
 const normalize=w=>(w.toLowerCase().match(/[\p{L}\p{N}]+/gu)||[]);
 const terms=new Set(normalize(query).filter(w=>!stop.has(w)&&(w.length>2||/^\d+$/.test(w))));
 let chosen="",score=-1;
 const paragraphs=String(text).split(/\n+/).map(p=>p.trim()).filter(p=>p.split(/\s+/).length>=8);
 for(const paragraph of paragraphs){
  const words=paragraph.split(/\s+/);
  for(let i=0;i<Math.max(1,words.length-24);i++){
   const part=words.slice(i,i+25),found=new Set(part.flatMap(normalize).filter(w=>terms.has(w)));
   const next=[...found].reduce((sum,w)=>sum+(/^\d+$/.test(w)?3:1),0);
   if(next>score){chosen=part.join(" ");score=next;}
  }
 }
 return chosen||String(text).trim().split(/\s+/).slice(0,25).join(" ");
}

helpers.collect:
async function collect(index,reuse=false) {
 const plan=load("c_plan"),s=plan.sources[index];
 const parse=eval("("+load("c_parse")+")"),en=eval("("+load("c_english")+")"),clean=eval("("+load("c_clean")+")"),quote=eval("("+load("c_excerpt")+")");
 const stamp=async()=>(await tools.clock__curr_time({})).current_time.replace(" UTC","+00:00").replace(" ","T");
 let data=reuse?load("c_search_"+index):null;
 if(!data){data={started:await stamp(),result:await tools.web__run({search_query:[{q:s.query}],response_length:"short"})};store("c_search_"+index,data);}
 const records=parse(data.result);
 if(!records.length&&!/no (?:search )?results|no matching|did not match|empty search/i.test(String(data.result)))throw Error("Unparsed search response for "+s.source_id+"; inspect cached tool response before continuing");
 const valid=records.filter(r=>{
  const match=r.url.match(/^https:\/\/([^/?#:@]+)(?:[/?#]|$)/i);
  return !!match&&!r.title.startsWith("<visual_element")&&!/(^|\.)(wikipedia|wikimedia|wikidata|wiktionary|wikiquote|wikisource)\.org$/i.test(match[1])&&en(r.body);
 });
 const primary=r=>/(?:\.edu|\.ac\.|\.gov|provinz|province|comune|gemeinde|unibz|unibo|eurac|bolzano-bozen|suedtirol\.info|pewresearch|vatican|\.uni-)/i.test(r.url)?1:0;
 valid.sort((a,b)=>primary(b)-primary(a)||a.rank-b.rank);
 const seen=new Set();
 const distinct=valid.filter(r=>{const key=r.url.split("#")[0].replace(/([?&])(?:utm_[^=]*|trk|fbclid|gclid)=[^&#]*/gi,"$1").replace(/[?&]+$/,"");if(seen.has(key))return false;seen.add(key);return true;});
 const selected=distinct.slice(0,2),sources=[],failures=[];
 for(const r of selected){
  let opened=load("c_open_url_"+r.url);
  if(!opened){opened=await tools.web__run({open:[{ref_id:r.url}],response_length:"short"});store("c_open_url_"+r.url,opened);}
  const text=clean(opened),ref=String(opened).match(/cite([^]+)/)?.[1]||r.ref;
  const snippetOnly=!text||!en(text)||/\.pdf(?:[?#]|$)/i.test(r.url);
  if(!text||!en(text))failures.push({url:r.url,reason:"No usable English page text returned; any cached text for this URL is labelled search_snippet."});
  const evidenceText=snippetOnly?r.body:text;
  const known=load("c_url_quote_"+r.url),textQuote=known||quote(evidenceText,s.query);
  if(!known)store("c_url_quote_"+r.url,textQuote);
  sources.push({reference_id:"WEB"+(sources.length+1),url:r.url,title:r.title,text:textQuote,retrieved_at:await stamp(),
    provider_ref:snippetOnly?r.ref:ref,evidence_kind:snippetOnly?"search_snippet":"page_excerpt"});
 }
 const entry={source_id:s.source_id,query:s.query,provider:"codex_web_tool",searched_at:data.started,status:sources.length?"ok":"no_results",sources,failures,search_ref:records.map(r=>r.ref).join(",")||"provider_returned_no_results"};
 const audit={source_id:s.source_id,query:s.query,searched_at:data.started,results:records.map(({title,url,ref,rank})=>({title,url,provider_ref:ref,rank})),attempted_urls:selected.map(r=>r.url),collector:"AI-assisted source selection using English-text and primary-domain heuristics; fixed 25-word extractive windows; PDF/blocked pages use explicitly labelled search snippets."};
 const root="/Users/adriannahampelska/Desktop/tum/thesis/grounded-generative-alignment-clean/data/search/grounded_c_web_development_v1/";
 for(const [dir,value]of[["sources",entry],["audit",audit]]){
  const path=root+dir+"/"+s.source_id.replaceAll(":","_")+".json";
  await tools.apply_patch("*** Begin Patch\n*** Add File: "+path+"\n"+JSON.stringify(value,null,2).split("\n").map(l=>"+"+l).join("\n")+"\n*** End Patch");
 }
 store("c_cache_"+index,entry);
 return {index,source_id:s.source_id,status:entry.status,sources:sources.map(r=>({url:r.url,kind:r.evidence_kind})),failures:failures.length};
}
